sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

if (!source.u_matched_skill || source.u_matched_skill.trim() == '') {
   ignore = true;
   return;
}


var userGR = new GlideRecord('x_kp101_kpmg_res_0_resource_profile'); 
userGR.addQuery('resource_name.name', source.u_name);
userGR.query();
if (!userGR.next()) {
   ignore = true;
   gs.info("User not found: " + source.u_name);
   return;
}

var skillGR = new GlideRecord('x_kp101_kpmg_res_0_skills');
skillGR.addQuery('name', source.u_matched_skill);
skillGR.query();
if (!skillGR.next()) {
   ignore = true;
   gs.info("Skill not found: " + source.u_matched_skill);
   return;
}
var dupCheck = new GlideRecord('x_kp101_kpmg_res_0_user_skill');
dupCheck.addQuery('user', userGR.sys_id);
dupCheck.addQuery('skill', skillGR.sys_id);
dupCheck.query();
if (dupCheck.hasNext()) {
   ignore = true;
   return;
}

target.user = userGR.sys_id;
target.skill = skillGR.sys_id;


})(source, map, log, target);
